
;(function ($, window, document, undefined) {
    var pluginName = "editable",
        defaults = {
            keyboard: true,
            dblclick: true,
            button: true,
            buttonSelector: ".edit",
            buttonCancel: '.cancel',
            maintainWidth: true,
            dropdowns: {},
            checkboxs: {},
            radios: {},
            images: {},
            repeater: {},
            edit: function() {},
            save: function() {},
            cancel: function() {}
        };

    function editable(element, options) {
        this.element = element;
        this.options = $.extend({}, defaults, options) ;

        this._defaults = defaults;
        this._name = pluginName;

        this.init();
    }
    //console.log('options: ', options);
    editable.prototype = {
        init: function() {
            this.editing = false;

            if (this.options.dblclick) {
                $(this.element)
                    .css('cursor', 'pointer')
                    .bind('dblclick', this.toggle.bind(this));
            }

            if (this.options.button) {
                $(this.options.buttonSelector, this.element).bind('click', this.toggle.bind(this));
                $(this.options.buttonCancel, this.element).bind('click', this.toggle.bind(this));
            }
        },

        toggle: function(e) {
            e.preventDefault();

            this.editing = !this.editing;
            if($(e.target).hasClass('wpformbuilder-cancel-database')){
                this.cancel();
            }else{
                if (this.editing) {
                    this.edit();
                } else {
                    this.save();
                }
            }
        },

        edit: function() {
            var instance = this,
                values = {};
            $('td[data-field]', this.element).each(function() {
                var input, repeaterHtml = [], repeatersName,
                    field = $(this).data('field'),
                    type = $(this).data('type'),
                    value = $(this).text(),
                    elementThis = this,
                    width = $(this).width();
                values[field] = value;
                let repeaterLabel;

                $(this).empty();

                if (instance.options.maintainWidth) {
                    $(this).width(width);
                }
                if(field in instance.options.repeater){
                    //alert(1);
                    let repeaterObj = $(this).closest('tr').attr('data-object');
                    repeaterObj = JSON.parse(repeaterObj);
                    repeatersName = repeaterObj.name;
                    //console.log('0410', repeaterObj);
                    $.each(repeatersName, function(key, value){
                        //console.log('5566', key, value);
                        let html = '';
                        repeaterLabel = repeaterObj.label[key] ? '<span style="font-weight:600;">'+repeaterObj.label[key]+':&#160;</span>' : '';
                        //console.log('33333', key);
                        input = get_html_edit_table(instance, field, repeaterObj.value[key], repeaterObj.type[key], repeaterObj.name[key], key, elementThis);
                        console.log('99999999', input);
                        switch (repeaterObj.type[key]){
                            case 'select':
                                repeaterHtml.push('<div class="sun-repeater-submissions-item">' + repeaterLabel+input[0].outerHTML + '</div>')
                                break;
                            case 'checkbox':
                            case 'radio':
                                let checkboxHtml = '<div class="sun-repeater-submissions-item">' + repeaterLabel;
                                $.each(input, function(){
                                    checkboxHtml += this.outerHTML;
                                });
                                checkboxHtml += '</div>';
                                repeaterHtml.push(checkboxHtml);
                                break;
                            default:
                                input.attr('value', repeaterObj.value[key]);
                                repeaterHtml.push('<div class="sun-repeater-submissions-item submition-'+repeaterObj.type[key]+'-item">'+repeaterLabel + input[0].outerHTML+'</div>');
                        }
                    });
                    repeaterHtml = repeaterHtml.join('');
                    $(this).html(repeaterHtml);
                    //$(repeaterHtml).appendTo(this);
                }else{
                    input = get_html_edit_table(instance, field, value, type, false, false, this);
                    //console.log('value: ', value);
                    input.appendTo(this);
                }
                if (instance.options.keyboard) {
                    //input.keydown(instance._captureKey.bind(instance));
                }
            });

            this.options.edit.bind(this.element)(values);
        },

        save: function() {
            var instance = this, tableElement, tableRepeater = false,
                values = {};
            $('td[data-field]', this.element).each(function() {
                let type = $(this).closest('tr').data('type');
                let value, repeaterHtml = '', that = this;
                tableElement = this
                if(type == 'repeater'){
                    tableRepeater = true;
                    value = {};
                    let reObj = $(this).closest('tr').attr('data-object');
                    reObj = JSON.parse(reObj);
                    console.log('1221', reObj);
                    let reType = reObj.type;
                    $.each(reType, function(key, type){
                        value[reObj.name[key]] = get_save_value_edit_table(type, reObj.name[key], key, that);
                        //console.log('jajaja', value[reObj.name[key]]);
                    });
                    repeaterHtml = getHtmlSaveRepeaterTable(reObj, value);

                }else{
                    value = get_save_value_edit_table(type, false, false, this);
                }
                values[$(this).data('field')] = value;
                values['post_id'] = $(this).data('post-id');
                values['repeater_key'] = $(this).closest('tr').attr('data-repeater-key') ? $(this).closest('tr').attr('data-repeater-key') : false;
                if(!['checkbox', 'radio'].includes(type) && type != 'repeater'){
                    $(this).empty().text(value);
                }else if(type == 'repeater'){
                    //console.log('haha', repeaterHtml);
                    $(this).empty().html(repeaterHtml.join(''));
                }
            });
            this.options.save.bind(this.element)(values, tableElement, tableRepeater);
        },

        cancel: function() {
            var instance = this,
                values = {};
            $('td[data-field]', this.element).each(function() {
                let type = $(this).closest('tr').data('type');
                let value, elements, repeaterText, dataOjb;
                switch (type){
                    case 'image_upload':
                        value = $('img', this)
                        break;
                    case 'checkbox':
                    case 'radio':
                        let oldValue = $(this).data('old-value').toString();
                        console.log('oldValue---->: ', oldValue);
                        oldValue = oldValue.split(',');
                        elements = $('input', this);
                        $.each(elements, function(){
                            if(oldValue.includes($(this).val())){
                                $(this).prop('checked', true);
                            }else{
                                $(this).prop('checked', false);
                            }
                            $(this).prop('disabled', true);
                        });
                        break;
                    case 'repeater':
                        dataOjb = $(this).closest('tr').attr('data-object');
                        dataOjb = JSON.parse(dataOjb);
                        repeaterText = get_repeater_cancel_text(dataOjb);
                        $(this).empty().html(repeaterText.join(''));
                        break;
                    default:
                        value = $(':input', this).data('old-value');
                        $(this).empty().text(value);
                }
                values[$(this).data('field')] = value;
            });

            this.options.cancel.bind(this.element)(values);
        },

        _captureEvent: function(e) {
            e.stopPropagation();
        },

        _captureKey: function(e) {
            if (e.which === 13) {
                this.editing = false;
                this.save();
            } else if (e.which === 27) {
                this.editing = false;
                this.cancel();
            }
        }
    };

    $.fn[pluginName] = function(options) {
        return this.each(function () {
            if (!$.data(this, "plugin_" + pluginName)) {
                $.data(this, "plugin_" + pluginName,
                new editable(this, options));
            }
        });
    };
    function get_html_edit_table(instance, field, value, type, name = false, repeaterKey = false, element){
        //console.log('1234', repeaterKey);
        let input = '', checked, labels, options, obj, checkboxs, radios, radioKey;
        obj = $(element).closest('tr').attr('data-object');
        obj = JSON.parse(obj);
        //console.log('obj: ', obj, type, name, repeaterKey);
        switch (type){
            case 'checkbox':
                checked = name ? obj.value[repeaterKey] : instance.options.checkboxs[field].value;
                labels = name ? obj.labels[name] : instance.options.checkboxs[field].labels;
                checkboxs = name ? obj.options[name] : instance.options.checkboxs[field].options;
                //console.log('checked-->: ', instance.options.checkboxs[field]);
                $(element).attr('data-old-value', checked);
                //console.log('hehe', checked);
                checked = !Array.isArray(checked) ? checked.split(',') : checked;
                //console.log('checked: ', checked);
                $.each(checkboxs, function(key, val){
                    //console.log('val: ', key, val);
                    if(checked.includes(val['value'])){
                        input += '<label class="wpformbuilder-editor-checkbox"><input type="checkbox" name="'+name+'" value="'+val['value']+'" class="wpformbuilder-form__input chexbox" checked>'+val['label']+'</label>';
                    }else{
                        input += '<label class="wpformbuilder-editor-checkbox"><input type="checkbox" name="'+name+'" value="'+val['value']+'" class="wpformbuilder-form__input chexbox">'+val['label']+'</label>';
                    }
                });
                input = $(input)
                break;
            case 'radio':
                //alert('1111');
                //console.log('hahahahahaha', obj);
                checked = name ? obj.value[repeaterKey] : instance.options.radios[field].value;
                labels = name ? obj.labels[name] : instance.options.radios[field].labels;
                radioKey = name ? obj.key : '';
                $(element).attr('data-old-value', checked);
                //console.log('$(this): ', $(this));
                checked = !Array.isArray(checked) ? checked.split(',') : checked;
                radios = name ? obj.options[name] : instance.options.radios[field].options;
                name = repeaterKey != false ? name+radioKey : name;
                
                $.each(radios, function(key, value){
                    if(checked.includes(value['value'])){
                        input += '<label class="wpformbuilder-editor-checkbox"><input type="radio" name="'+name+'" value="'+value['value']+'" class="wpformbuilder-form__input chexbox" checked>'+value['label']+'</label>';
                    }else{
                        input += '<label class="wpformbuilder-editor-checkbox"><input type="radio" name="'+name+'" value="'+value['value']+'" class="wpformbuilder-form__input chexbox">'+value['label']+'</label>';
                    }
                })
                    input = $(input);
                break;
            case 'select':
                input = $('<select name="'+name+'" style="width:100%"></select>');
                options = instance.options.dropdowns[field] ? instance.options.dropdowns[field] : instance.options.repeater.repeater.options[name];
                for (let i = 0; i < options.length; i++) {
                    if(options[i] == value){
                        $('<option selected></option>').text(options[i]).appendTo(input);
                    }else{
                        $('<option></option>').text(options[i]).appendTo(input);
                    }
                };
                input.attr('data-old-value', value).dblclick(instance._captureEvent);
                break;
            default:
                input = $('<input name="'+name+'" type="'+type+'" style="width:100%" />')
                .val(value)
                .attr('data-old-value', value)
                .dblclick(instance._captureEvent);
        }
        return input;
    }
    function get_repeater_cancel_text(data){
        let textContent = [], name = data.name, type = data.type, reValue = data.value, label = data.label, labels;
        $.each(type, function(key, tp){
            options = data.options;
            let html = label[key] ? '<div class="sun-repeater-submissions-item"><span style="font-weight:600;">'+label[key]+':&#160;</span>' : '<div class="sun-repeater-submissions-item">';
            switch (tp){
                case 'checkbox':
                case 'radio':
                    labels = data.labels[name[key]];
                    options = options[name[key]];
                    $.each(options, function(k, v){
                        if(reValue[key].includes(v)){
                            html += '<label class="sun-cancel-'+tp+'"><input type="'+tp+'" value="'+v+'" checked disabled>'+labels[k]+'</label>';
                        }else{
                            html += '<label class="sun-cancel-'+tp+'"><input type="'+tp+'" value="'+v+'" disabled>'+labels[k]+'</label>';
                        }
                    });
                    textContent.push(html+'</div>');
                    break;
                default:
                    textContent.push(html+data.value[key] + '</div>');
            }
            //html += '</div>';
        });
        return textContent;
    }
    function get_save_value_edit_table(type, name, key = false, element){
        let value;
        //console.log(name);
        switch (type) {
            case 'image_upload':
                let imageHtml = '';
                $.each($('img', element), function(){
                    value = $(thielements).attr('src');
                    imageHtml += '<img width="150" height="150" src="'+value+'" style="margin-right:5px;">';
                })
                $(element).empty().append(imageHtml);
                break;
            case 'radio':
                let dataRadio = $(element).closest('tr').data('object');
                let radioKey = key != false ? dataRadio.key : '';
                //console.log($('input[type="radio"][name="'+name+radioKey+'"]', element), name+radioKey);
                //return false;
                let radioValues = [];
                $.each($('input[type="radio"][name="'+name+radioKey+'"]', element), function(){
                    if($(this).is(':checked')){
                        radioValues.push($(this).val())
                    }
                    $(this).prop('disabled', true);
                });
                value = radioValues.join()
                dataRadio.value = value;
                $(element).closest('tr').attr('data-object', JSON.stringify(dataRadio));
                break;
            case 'checkbox':
                let dataChekbox = $(element).closest('tr').data('object');
                let checkboxvalues = [];
                //return false;
                //console.log($('input', element));
                $.each($('input[type="checkbox"][name="'+name+'"]', element), function(){
                    if($(this).is(':checked')){
                        checkboxvalues.push($(this).val())
                    }
                    $(this).prop('disabled', true);
                });
                value = checkboxvalues.join();
                dataChekbox.value = checkboxvalues.join();
               // $(element).closest('tr').attr('data-object', JSON.stringify(dataChekbox));
                break;
            default:
                if(['text', 'number', 'url', 'tel', 'phone', 'email'].includes(type)){
                    //console.log($(':input', element));
                    value = key == false ? $(':input', element).val() : $(':input[type="'+type+'"][name="'+name+'"]', element).val();
                }else{
                    value = value ? value : $('select[name="'+name+'"]', element).val();
                }
        }
        return value;
    }
    //Đang ở đây
    function getHtmlSaveRepeaterTable(data, elementValue){
        let repeaterValue = Object.values(elementValue);
        let type = data.type, html = [], itemHtml, labelItems, checked, items, name = data.name, labels = data.labels, label = data.label;
        $.each(type, function(key, tp){
            itemHtml = '<div class="sun-repeater-submissions-item"><span style="font-weight:700">'+label[key]+':&#160;</span>';
            switch(tp){
                case 'checkbox':
                case 'radio':
                    labelItems = '';
                    items = data.options[name[key]];
                    labelItems = labels[name[key]];
                    checked = repeaterValue[key];
                    $.each(items, function(k, val){
                        if(checked.includes(val)){
                            itemHtml += '<label class="sun-editor-checkbox"><input type="'+tp+'" value="'+val+'" class="sun-form__input chexbox" disabled checked>'+labelItems[k]+'</label>';
                        }else{
                            itemHtml += '<label class="sun-editor-checkbox"><input type="'+tp+'" value="'+val+'" class="sun-form__input chexbox" disabled>'+labelItems[k]+'</label>';
                        }
                    });
                    itemHtml += '</div>';
                    html.push(itemHtml);
                    break;
                default:
                    html.push(itemHtml + repeaterValue[key] + '</div>');
            }
        })
        return html;
    }

})(jQuery, window, document);
